mapper.sql:

WHERE c.DELETE_YN =


        1


        0





    AND c.PROGRESS_STATUS = #{progressStatus}




    AND c.POST_STATUS = #{postStatus}





    AND (
        LOCATE(#{keyword}, c.TITLE) > 0
        OR LOCATE(#{keyword}, c.CONTENT) > 0
    )





    AND c.END_DATE > #{fromDate}




    AND c.START_DATE < DATE_ADD(#{toDate}, INTERVAL 1 DAY)

mapper.select:
SELECT
    EXISTS (
        SELECT 1
        FROM CHALLENGE_ENTRY ce
        WHERE ce.CHAL_CODE = #{code}
    )
    OR
    EXISTS (
        SELECT 1
        FROM FEED f
        WHERE f.CHAL_CODE = #{code}
    )

SELECT EXISTS (
    SELECT 1
    FROM CHALLENGE
    WHERE CODE = #{code}
)

mapper.sql:
WHERE ce.CHAL_CODE = #{code}
  AND ce.STATUS IN ('JOINED', 'COMPLETED')
  AND ce.CANCELED_AT IS NULL

mapper.select:
SELECT COUNT(*)
FROM FEED f

WHERE f.CHAL_CODE = #{code}
  AND f.DELETE_YN = 0
  AND f.CREATED_AT >= #{start}
  AND f.CREATED_AT < #{end}

SELECT COUNT(*)

FROM (

) p

WHERE p.FIRST_JOINED_AT >= #{start}
  AND p.FIRST_JOINED_AT < #{end}
